export const ACADEMY_CONTENT = Object.freeze({"locale":"vi","lessons":[{"ep":1,"title":"Một bitcoin đắt như vậy. Tôi vẫn có thể mua một phần chứ?","goal":"Phân biệt số lượng coin với số tiền chi ra, và hiểu rằng bitcoin có thể mua theo phần lẻ.","task":"Trong bảng luyện tập, quy đổi số tiền chi 100 thành số lượng coin. Không có lệnh thực tế nào được tạo.","answer":"0.002 BTC (chưa trừ phí).","takeaways":["Giá của một bitcoin không phải là số tiền cần để bắt đầu.","Bitcoin chia được thành số thập phân: chi 100 ở giá 50,000 thì bạn có 0.002 BTC.","Mỗi nền tảng tự đặt mức lệnh tối thiểu và phí riêng, nên hãy kiểm tra cả hai trước."],"quiz":{"q":"Một bitcoin có giá 50,000 USDT. Bạn chi 100 USDT, chưa tính phí. Bạn nhận được gì?","options":["Không gì cả, bạn cần cả một đồng","0.002 BTC","0.02 BTC"],"answer":1,"why":"100 ÷ 50,000 = 0.002. Bạn có thể sở hữu một phần của một bitcoin."},"transcript":[{"t":0.25,"who":"sam","text":"Một đồng đắt thế này sao? Tiền của tôi chắc chẳng đủ mua vé vào cửa."},{"t":9.25,"who":"nexubo","text":"Đó là giá của một đồng nguyên vẹn, không phải số tiền bạn phải trả mỗi lần. Bitcoin là tài sản số và có thể sở hữu theo số thập phân. Thường bạn không cần mua cả đồng."},{"t":25.25,"who":"narrator","text":"Một bài tập giả định: Giả sử một bitcoin giá 50,000 USDT và bạn chi 100. Bỏ qua phí, bạn nhận được 0.002 bitcoin. Đây không phải giá thị trường hôm nay."},{"t":45.25,"who":"sam","text":"Thế khi giá thay đổi thì sao?"},{"t":47,"who":"nexubo","text":"Số lượng coin có thể giữ nguyên, nhưng giá trị quy đổi sẽ tăng hoặc giảm. Mua ít nghĩa là bỏ ít vốn hơn, không đồng nghĩa là không có rủi ro."},{"t":62.25,"who":"nexubo","text":"Có thể chia nhỏ, nhưng không phải nền tảng nào cũng nhận lệnh cực nhỏ. Hãy kiểm tra số tiền tối thiểu và phí. Khi đang học, hãy dùng tiền mô phỏng. Không cần nạp tiền."},{"t":75.25,"who":"narrator","text":"Bạn có bắt buộc phải mua trọn vẹn một bitcoin không? Không. Hãy nhớ: giá của một đồng không phải là rào cản bắt đầu."},{"t":86.25,"who":"narrator","text":"Hầu hết các giao dịch đều định giá bằng USDT. Nhưng USDT có thực sự là đô la không? Đón xem tập tiếp theo."},{"t":92.55,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":2,"title":"USDT có phải là đô la không? Tại sao mua coin lại thấy nó khắp nơi?","goal":"Hiểu công dụng, mục tiêu neo giá và rủi ro của stablecoin; biết rằng không nhất thiết phải mua USDT trước.","task":"Xếp 'tiền gửi ngân hàng bằng USD', 'USDT' và 'BTC' vào các danh mục đúng.","answer":"USDT là một stablecoin, thuộc loại tài sản crypto. Nó không phải là tiền gửi ngân hàng bằng USD.","takeaways":["USDT là stablecoin được thiết kế để giữ giá gần một đô la, không phải tiền gửi ngân hàng.","Các sàn dùng nó để định giá và hoán đổi tài sản, nên một lệnh bán thường kết thúc bằng USDT.","\"Ổn định\" là mục tiêu thiết kế: giá có thể lệch và việc quy đổi có điều kiện."],"quiz":{"q":"Câu nào về USDT là đúng?","options":["Đó là số đô la trong tài khoản ngân hàng của bạn","Đó là một stablecoin, một loại tài sản crypto","Nó không bao giờ có thể lệch khỏi một đô la"],"answer":1,"why":"USDT nhằm bám theo đồng đô la, nhưng nó là tài sản crypto với rủi ro riêng từ đơn vị phát hành và nền tảng."},"transcript":[{"t":0.25,"who":"sam","text":"Nó tên là Tether, vậy về cơ bản là tiền đô gửi ngân hàng đúng không?"},{"t":9.25,"who":"nexubo","text":"Không phải. USDT, hay Tether, là một stablecoin. Nó được thiết kế để giữ giá sát một đô la. Nhưng nó không phải tiền trong tài khoản ngân hàng và không hề phi rủi ro."},{"t":25.25,"who":"narrator","text":"Các sàn giao dịch thường dùng nó để định giá và giao dịch. Bạn có thể mua bitcoin bằng USDT và khi bán cũng có thể nhận lại USDT chứ không phải chuyển khoản ngân hàng."},{"t":45.25,"who":"nexubo","text":"'Ổn định' là mục tiêu thiết kế, không phải sự bảo đảm. Giá có thể biến động; phát hành và rút vốn đều có điều kiện. Hãy tìm hiểu rủi ro từ đơn vị phát hành và nền tảng."},{"t":62.25,"who":"sam","text":"Vậy tôi phải mua USDT trước khi mua bitcoin sao?"},{"t":65.23,"who":"nexubo","text":"Không nhất thiết. Việc hỗ trợ loại tiền tệ và cặp giao dịch nào phụ thuộc vào khu vực và nền tảng của bạn."},{"t":75.25,"who":"narrator","text":"Câu này sai ở điểm nào? Stablecoin không phải là cam kết bảo toàn vốn. Hãy hiểu rõ công dụng và biết rằng nó vẫn có thể mất ổn định."},{"t":86.25,"who":"narrator","text":"Nếu tối nay điện thoại bị hỏng, coin của bạn có mất luôn không? Tập tiếp theo: Coin thực sự nằm ở đâu."},{"t":92.15,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?","goal":"Phân biệt tài khoản giám sát trên sàn với ví tự quản lý, hiểu rõ quyền kiểm soát và trách nhiệm khôi phục.","task":"Nối hai trường hợp: tài khoản đăng nhập trên sàn giao dịch và ví tự quản lý thông thường dùng cụm từ khôi phục.","answer":"Chúng khác nhau về quyền kiểm soát và cơ chế khôi phục. Tự quản lý không đồng nghĩa với an toàn tự động.","takeaways":["Với tài khoản trên sàn, nền tảng là bên chủ yếu quản lý tài sản và khóa.","Với ví tự lưu ký, bạn kiểm soát thông tin truy cập, và trách nhiệm khôi phục thuộc về bạn.","Trước khi chọn, hãy hỏi: ai nắm quyền di chuyển tài sản?"],"quiz":{"q":"Bạn làm mất cụm từ khôi phục của một ví tự lưu ký thông thường và không có cách khôi phục nào khác. Điều gì xảy ra?","options":["Bộ phận hỗ trợ có thể đặt lại cho bạn","Bạn có thể mất quyền truy cập vĩnh viễn","Sàn sẽ tự động khôi phục"],"answer":1,"why":"Với tự lưu ký, bạn giữ khóa. Không có cụm từ hoặc cách hợp lệ khác, không ai khôi phục được cho bạn."},"transcript":[{"t":0.25,"who":"sam","text":"Điện thoại tôi hỏng rồi. Coin của tôi có mất theo không?"},{"t":9.25,"who":"nexubo","text":"Coin không nằm trong điện thoại. Ví giúp bạn xem tài sản trên blockchain và dùng khóa để ủy quyền thao tác. Khôi phục được hay không tùy thuộc vào loại ví và cách bạn sao lưu."},{"t":32.25,"who":"narrator","text":"Với tài khoản giám sát trên sàn, nền tảng quản lý tài sản và khóa, bạn thao tác qua tài khoản. Với ví tự quản lý, bạn tự kiểm soát khóa; sự tiện lợi và trách nhiệm phân chia khác nhau."},{"t":60.25,"who":"sam","text":"Quên mật khẩu ở bên nào cũng chỉ cần gọi hỗ trợ là xong sao?"},{"t":63.86,"who":"nexubo","text":"Đừng nghĩ như vậy. Với ví dùng cụm từ khôi phục tiêu chuẩn, nếu bạn mất cụm từ và không có phương thức dự phòng hợp lệ khác, hỗ trợ không thể lấy lại giúp bạn."},{"t":84.25,"who":"nexubo","text":"Để tài sản trên sàn chịu rủi ro nền tảng. Tự giữ có thể gặp sự cố vì lộ khóa hoặc cấp quyền nhầm. Hôm nay chỉ cần hiểu sự khác biệt, không cần chuyển hết đi ngay."},{"t":103.25,"who":"narrator","text":"Ai kiểm soát quyền di chuyển tài sản? Hãy trả lời câu hỏi đó trước. Sau đó mới quyết định bạn cần loại tài khoản hay ví nào."},{"t":116.25,"who":"narrator","text":"Hai cánh cửa trông giống hệt nhau. Một cửa là giả. Tập tiếp theo: Cách nhận biết cửa thật."},{"t":121.75,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":4,"title":"Tìm đúng cửa chính thức: Đừng mở tài khoản một cách mù quáng","goal":"Kiểm tra tên miền chính thức, yêu cầu khu vực và bật bảo mật cơ bản trước khi đăng ký.","task":"Tìm điểm bất thường trên thanh địa chỉ của một trang đăng ký giả lập.","answer":"Tên miền chính thức không khớp. Không nhập bất kỳ thông tin nào trên trang đáng ngờ.","takeaways":["Trước hết, hãy kiểm tra nền tảng có phục vụ quốc gia bạn thực sự sinh sống hay không.","Chỉ đăng ký qua lối vào chính thức đã xác nhận, bằng email hoặc số điện thoại của chính bạn.","Ngay sau khi đăng ký, hãy bật các tính năng bảo mật và lưu lại các phương án khôi phục."],"quiz":{"q":"Bạn nên xác nhận điều gì trước tiên, trước khi đăng ký?","options":["Giá trị phần thưởng chào mừng","Nền tảng phục vụ quốc gia của bạn và lối vào là chính thức","Nền tảng có bao nhiêu người theo dõi"],"answer":1,"why":"Điều kiện sử dụng và lối vào chính thức phải đến trước. Phần thưởng không bao giờ nên quyết định nơi bạn mở tài khoản."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi tìm 'sàn giao dịch' trên mạng và thấy hàng loạt liên kết trông na ná nhau. Đâu mới là trang thật?"},{"t":9.25,"who":"nexubo","text":"Đừng bấm bừa bãi. Trước khi đăng ký, hãy kiểm tra bốn điều: tên miền chính thức, yêu cầu khu vực, sản phẩm khả dụng và bảo mật tài khoản."},{"t":32.25,"who":"narrator","text":"Sau khi xác nhận cổng chính thức, hãy đăng ký bằng email hoặc số điện thoại của chính bạn, đặt mật khẩu riêng và hoàn tất xác thực. Không bao giờ mua tài khoản người khác hay giả mạo danh tính."},{"t":60.25,"who":"nexubo","text":"Đăng ký chưa phải bước cuối. Hãy bật các lớp bảo mật hỗ trợ, kiểm tra thiết bị đăng nhập và lưu phương thức khôi phục. Đừng bao giờ gửi mã OTP cho người tự xưng là hỗ trợ viên."},{"t":84.25,"who":"narrator","text":"Trang web của chúng tôi giúp bạn tra cứu thông tin, nhưng quan hệ đối tác không phải là bảo đảm an toàn. Khi thông tin chưa được xác nhận, đừng vội mở tài khoản."},{"t":103.25,"who":"sam","text":"Dừng lại. Hãy xác nhận điều kiện hợp lệ và quy định trước."},{"t":107.02,"who":"nexubo","text":"Đúng rồi. Nhận đúng cửa trước, mở tài khoản sau."},{"t":116.25,"who":"nexubo","text":"Bạn muốn một cánh cửa đáng tin cậy? NexuAlpha liệt kê các cổng chính thức đã xác minh. Liên kết đối tác OKX đưa bạn đến thẳng trang chính thức và mã nexu888 giúp hoàn phí."},{"t":127.35,"who":"narrator","text":"Làm ngay: Bật xác thực hai bước khi đăng nhập. Tập tiếp theo: Có người trong đoạn chat ngỏ ý 'làm KYC hộ bạn'."},{"t":134.45,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":5,"title":"KYC thực hiện như thế nào và ai mới là người nhận giấy tờ của bạn?","goal":"Hiểu mục đích và quy trình xác minh danh tính, chỉ gửi qua các kênh chính thức đã xác minh.","task":"Sắp xếp thứ tự các bước xác minh bằng thông tin giả định. Tuyệt đối không tải giấy tờ thật lên khóa học.","answer":"Xác minh cổng vào → gửi thông tin thật theo yêu cầu khu vực → chờ và kiểm tra kết quả.","takeaways":["KYC xác nhận bạn là chủ tài khoản và giúp nền tảng tuân thủ quy định.","Chỉ gửi giấy tờ tùy thân trong quy trình xác minh chính thức, không bao giờ gửi qua tin nhắn.","Nếu thất bại, hãy đọc lý do, sửa lại và thử lại bằng danh tính thật của bạn."],"quiz":{"q":"Ai nên nhận giấy tờ tùy thân của bạn?","options":["Một \"nhân viên\" nhiệt tình trong nhóm chat","Chỉ quy trình xác minh chính thức đã được kiểm chứng","Nhóm chat của khóa học, để người khác kiểm tra giúp"],"answer":1,"why":"Chỉ quy trình chính thức. NexuAlpha không bao giờ yêu cầu giấy tờ của bạn, và người lạ cũng không nên yêu cầu."},"transcript":[{"t":0.25,"who":"sam","text":"Hệ thống yêu cầu giấy tờ tùy thân. Còn người này lại bảo có thể làm hộ tôi?"},{"t":9.25,"who":"nexubo","text":"Xác thực danh tính là để kiểm tra chính chủ tài khoản và tuân thủ quy định. Hãy chắc chắn đó là luồng chính thức, đừng giao giấy tờ hay mã OTP cho người nhận làm hộ trên mạng."},{"t":32.25,"who":"narrator","text":"Thông thường bạn điền thông tin thật, tải lên giấy tờ hợp lệ được hỗ trợ, sau đó chụp ảnh hoặc quét khuôn mặt theo hướng dẫn. Giấy tờ nào được chấp nhận tùy vào khu vực và sàn."},{"t":60.25,"who":"nexubo","text":"Nếu không đạt, hãy xem lý do trước: Giấy tờ hết hạn? Bị lóa sáng? Tên không khớp? Sửa theo hướng dẫn, đừng bao giờ thử lại bằng danh tính giả."},{"t":84.25,"who":"sam","text":"Làm xong là có thể giao dịch được ngay chứ?"},{"t":86.78,"who":"nexubo","text":"Không đảm bảo. Kết quả xét duyệt, sản phẩm được dùng và việc nạp tiền đều theo thông báo chính thức. Khóa học này cũng không bao giờ thu thập giấy tờ thật của bạn."},{"t":103.25,"who":"narrator","text":"Giao giấy tờ cho ai? Chỉ gửi qua quy trình chính thức đã xác minh. Không giao cho chúng tôi, và không giao cho người lạ."},{"t":116.25,"who":"nexubo","text":"Sẵn sàng xác minh? Chỉ bắt đầu trên trang web chính thức. Liên kết đối tác OKX đưa bạn đến thẳng trang chủ cùng mã nexu888 hoàn phí. Chúng tôi không bao giờ hỏi giấy tờ của bạn."},{"t":127.25,"who":"narrator","text":"Nạp tiền, mua coin, chuyển quỹ: ba nút bấm trông na ná nhau. Tập tiếp theo: Nên bấm nút nào."},{"t":132.85,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":6,"title":"Lần nạp tiền đầu tiên: Tiền đến từ đâu và đi về đâu?","goal":"Phân biệt nạp tiền pháp định, mua trực tiếp, nạp crypto và chuyển quỹ nội bộ; kiểm tra kênh và phí.","task":"Nối ba tình huống: Nạp tiền pháp định qua ngân hàng, nạp tiền mã hóa đã có sẵn và chuyển quỹ nội bộ giữa các tài khoản.","answer":"Các đường dẫn khác nhau có quy tắc, phí và thời gian khác nhau. Chuyển quỹ nội bộ không qua blockchain.","takeaways":["Nạp tiền pháp định, mua crypto, nạp on-chain và chuyển nội bộ là những con đường khác nhau.","Nạp on-chain cần đúng đồng coin và mạng được hỗ trợ; chuyển nội bộ thì vẫn nằm trong nền tảng.","Không bao giờ trả tiền cho người lạ bên ngoài nền tảng; hãy kiểm tra trước số dư sẽ về đâu."],"quiz":{"q":"Bạn chuyển USDT từ tài khoản cấp vốn sang tài khoản giao dịch trên cùng một nền tảng. Đó là gì?","options":["Nạp on-chain","Chuyển nội bộ","Nạp tiền pháp định"],"answer":1,"why":"Nó chỉ di chuyển số dư giữa các tài khoản của chính bạn. Thường đó không phải là giao dịch on-chain."},"transcript":[{"t":0.25,"who":"sam","text":"Có ba nút: nạp tiền, mua coin và chuyển quỹ. Chẳng phải nút nào cũng là để nạp tiền sao?"},{"t":9.25,"who":"nexubo","text":"Không phải. Chúng di chuyển các loại tài sản khác nhau. Bạn đang nạp tiền nội tệ, hay nạp coin đã có sẵn? Hay chỉ chuyển số dư giữa các tài khoản của bạn?"},{"t":32.25,"who":"narrator","text":"Nạp tiền pháp định thường cộng số dư tiền mặt vào tài khoản; mua trực tiếp là thanh toán xong nhận ngay crypto. Các kênh ngân hàng hoặc thẻ, phí và hạn mức đều khác nhau tùy sàn."},{"t":60.25,"who":"nexubo","text":"Nếu đã có crypto, bạn có thể nạp theo coin và mạng lưới được hỗ trợ. Chuyển quỹ nội bộ chỉ là điều chuyển số dư giữa các tài khoản, không phải giao dịch on-chain. Hãy xem tiền sẽ vào đâu."},{"t":84.25,"who":"narrator","text":"Một số sàn hỗ trợ giao dịch P2P giữa người dùng. Đó không phải tên gọi khác của chuyển khoản ngân hàng. Tuyệt đối không giao dịch ngoài nền tảng, không dùng nguồn tiền không rõ ràng."},{"t":103.25,"who":"sam","text":"Không được, đây là các kênh khác nhau."},{"t":105.59,"who":"nexubo","text":"Đúng rồi. Xem tài sản trước, nhìn lộ trình sau, cuối cùng kiểm tra tiền thực nhận."},{"t":116.25,"who":"narrator","text":"BTC/USDT: Dấu gạch chéo này có nghĩa là mua cả hai đồng không? Tập tiếp theo: Giao dịch giao ngay đầu tiên."},{"t":122.45,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":7,"title":"Giao dịch spot đầu tiên: Từ 100 đến 0.002 BTC","goal":"Hoàn thành một lệnh mua giao ngay mô phỏng với số tiền, số lượng và phí rõ ràng.","task":"Với số dư mô phỏng 1,000, mua 0.002 BTC. Kiểm tra số dư USDT còn lại 899.90 và lịch sử giao dịch.","answer":"Số tiền 100, phí 0.10, tổng chi 100.10; còn lại 899.90.","takeaways":["BTC/USDT nghĩa là bitcoin được định giá bằng USDT: bạn trả USDT và nhận bitcoin.","Kiểm tra ô đặt lệnh đang yêu cầu số tiền hay số lượng coin.","Sau khi mua, hãy xem lịch sử giao dịch: trạng thái khớp lệnh, giá trung bình và phí."],"quiz":{"q":"Bạn mua 0.002 BTC ở giá 50,000 với phí 0.1% trừ riêng bằng USDT. Tổng số tiền đã chi là bao nhiêu?","options":["100","100.10","110"],"answer":1,"why":"100 cho số coin cộng 0.10 phí thành 100.10."},"transcript":[{"t":0.25,"who":"sam","text":"Dấu gạch chéo này. Tôi phải mua cả hai loại coin sao?"},{"t":9.25,"who":"nexubo","text":"Không phải. Nó có nghĩa là bitcoin được định giá bằng USDT. Khi mua, bạn trả USDT và nhận bitcoin. Khi bán thì ngược lại."},{"t":35.25,"who":"narrator","text":"Chúng ta thực hành trên tài khoản mô phỏng. Chắc chắn là giao ngay (spot), không phải hợp đồng (futures). Chọn cặp, nhấn Mua và nhập số tiền. Kiểm tra xem ô nhập đòi hỏi số tiền hay số lượng coin."},{"t":67.25,"who":"nexubo","text":"Giả sử giá khớp là 50,000 và bạn chi 100. Bạn nhận 0.002 bitcoin. Giả định thêm phí 0.1% trừ riêng từ USDT, bạn chi tổng cộng 100.10. Quy định thực tế tùy thuộc vào sàn."},{"t":95.25,"who":"sam","text":"Vậy bấm Mua một cái là chắc chắn có coin rồi đúng không?"},{"t":99.07,"who":"nexubo","text":"Còn phải kiểm tra lịch sử khớp lệnh. Chưa khớp, khớp một phần và khớp toàn bộ là khác nhau. Hãy đối chiếu cả giá trung bình thực tế và phí."},{"t":116.25,"who":"narrator","text":"Bài thực hành đầu tiên không phải để đoán giá lên hay xuống, mà là để kiểm tra rõ năm yếu tố này. Khi xong, bạn hoàn toàn có thể chưa cần giao dịch thật vội."},{"t":131.25,"who":"nexubo","text":"Khi bạn sẵn sàng cho giao dịch thật đầu tiên, hãy mở Bitget qua liên kết đối tác của chúng tôi. Mã nexu888 giúp hoàn lại một phần phí giao dịch. Luôn làm đúng năm bước kiểm tra mỗi lần."},{"t":140.95,"who":"narrator","text":"Giả sử giá tăng và bạn bán ra. Vậy tại sao số dư ngân hàng vẫn không nhúc nhích? Đón xem tập sau."},{"t":146.85,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":8,"title":"Tôi đã bán rồi. Tại sao tiền vẫn chưa về tài khoản ngân hàng?","goal":"Phân biệt việc bán tài sản, nhận số dư stablecoin/tiền pháp định và rút tiền thực tế về ngân hàng.","task":"Hoàn thành một lệnh bán mô phỏng, sau đó đánh dấu trên sơ đồ dòng tiền bước nào mới là rút tiền về ngân hàng.","answer":"Bán lấy USDT không phải là rút tiền ngân hàng. Lợi nhuận ròng trong ví dụ này: 9.79.","takeaways":["Bán lấy USDT cho bạn số dư USDT, không phải tiền trong ngân hàng.","Bán và rút về ngân hàng là hai bước riêng biệt.","Giá cao hơn chưa phải lợi nhuận ròng: hãy trừ hết các khoản phí trước."],"quiz":{"q":"Bạn đã bán bitcoin lấy USDT. Tiền đang ở đâu?","options":["Trong tài khoản ngân hàng của bạn","Là số dư USDT trên nền tảng","Đã được đổi sang tiền tệ địa phương"],"answer":1,"why":"Bạn đã nhận USDT. Đưa tiền về ngân hàng là một bước rút tiền riêng."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi chắc chắn đã bán rồi. Vậy tại sao ngân hàng vẫn chưa nhận được tiền?"},{"t":9.25,"who":"nexubo","text":"Xem bạn đã bán sang cặp nào. Nếu bán ra USDT, bạn nhận được số dư USDT chứ không phải tiền vào ngân hàng. Bán coin và rút tiền về ngân hàng là hai bước riêng biệt."},{"t":35.25,"who":"narrator","text":"Vẫn ví dụ học tập đó: Bạn bán 0.002 bitcoin ở giá 55,000, được 110. Trừ đi phí giả định 0.11, tài khoản của bạn nhận 109.89."},{"t":67.25,"who":"sam","text":"Vậy là tôi lãi được mười à?"},{"t":68.76,"who":"nexubo","text":"Còn phải trừ chi phí. Ở đây là 9.79, chưa tính phí chuyển đổi sang tiền pháp định hay phí rút tiền. Giá tăng không đồng nghĩa với lợi nhuận ròng cuối cùng."},{"t":95.25,"who":"narrator","text":"Nếu cần rút tiền về ngân hàng, trước tiên hãy kiểm tra khu vực có hỗ trợ không. Sau đó rút qua kênh chính thức về tài khoản chính chủ. Kiểm tra tên, số tiền, phí và điều kiện xử lý."},{"t":116.25,"who":"sam","text":"Không phải."},{"t":116.98,"who":"nexubo","text":"Hãy lưu lại lịch sử giao dịch và rút tiền; nếu chưa rõ bản chất số dư, đừng chỉ dựa vào một thông báo 'thành công' để phán đoán."},{"t":131.25,"who":"narrator","text":"Một mạng rẻ hơn chút. Bấm nhầm một lần. Coin có thể không bao giờ tới. Tập tiếp theo: Những điểm tuyệt đối không được đoán mò."},{"t":137.95,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":9,"title":"Trước khi chuyển coin: Tuyệt đối không đoán mò những điểm này","goal":"Kiểm tra coin, mạng lưới, địa chỉ, memo và điều kiện nhận tiền; luôn gửi thử khoản nhỏ trước.","task":"Trong biểu mẫu rút coin mô phỏng có lỗi cố ý, hãy sửa mạng không khớp và điền memo còn thiếu; sau đó gửi thử khoản nhỏ mô phỏng.","answer":"Chỉ gửi khi mọi điều kiện then chốt đều khớp. Không có cơ chế mặc định 'tự động chuyển sang đúng mạng' bảo vệ bạn.","takeaways":["Xác nhận đồng coin và mạng mà bên nhận hỗ trợ trước khi gửi.","Sao chép địa chỉ từ trang nhận, kiểm tra toàn bộ và thêm memo hoặc tag nếu có.","Gửi một khoản thử nhỏ trước và xác nhận đã được ghi có."],"quiz":{"q":"Trang nhận yêu cầu memo. Bạn làm gì?","options":["Bỏ qua, địa chỉ là đủ","Điền memo chính xác như hiển thị","Dùng memo từ một lần chuyển cũ"],"answer":1,"why":"Nếu memo hoặc tag là bắt buộc, giao dịch có thể không được ghi có nếu thiếu nó."},"transcript":[{"t":0.25,"who":"sam","text":"Mạng này rẻ hơn. Cứ tùy tiện đổi sang nó không được sao?"},{"t":9.25,"who":"nexubo","text":"Trước tiên xác nhận người nhận hỗ trợ loại tài sản và mạng nào. Sau đó mới tính đến phí. Hai đầu không khớp thì dù rẻ cũng không được gửi. Cùng tên USDT cũng có thể ở các mạng khác nhau."},{"t":39.25,"who":"narrator","text":"Tạm coi mạng lưới là tuyến đường, địa chỉ là đích đến. Nhưng hai địa chỉ trông giống nhau chưa chắc đã tương thích cùng mạng. Phải kiểm tra sàn nhận có hỗ trợ chuỗi và tài sản đó không."},{"t":75.25,"who":"nexubo","text":"Sao chép địa chỉ từ trang nhận rồi đối chiếu toàn bộ. Điền memo hoặc tag nếu có yêu cầu. Xác nhận mức nạp tối thiểu, phí rút và số tiền thực nhận. Đừng chỉ nhìn vài ký tự đầu và cuối."},{"t":106.25,"who":"narrator","text":"Hãy gửi thử một khoản nhỏ đạt mức tối thiểu và xác nhận tiền đã vào tài khoản. Với khoản lớn sau đó, vẫn phải kiểm tra lại, không dùng lịch sử cũ một cách mù quáng. Khi tự quản lý ví, hãy chuẩn bị sẵn phí mạng."},{"t":130.25,"who":"sam","text":"Không thể."},{"t":131.16,"who":"nexubo","text":"Kiểm tra thêm một lần trước khi gửi đáng giá hơn nhiều so với việc đi tìm người cứu vãn sau khi chuyển nhầm."},{"t":146.25,"who":"narrator","text":"Báo 'thành công' nhưng tiền không tới. Đừng vội chuyển tiếp. Tập sau: Cần tra cứu ở đâu."},{"t":151.65,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":10,"title":"Báo đã gửi nhưng tiền chưa tới. Cần kiểm tra ở đâu?","goal":"Phân biệt khâu xử lý của bên gửi, xác nhận trên blockchain và ghi có của bên nhận; nắm rõ các hướng xử lý có giới hạn.","task":"Nối ba tình huống sự cố với: Bên gửi, trạng thái on-chain và bên nhận.","answer":"Xác định đúng trạng thái rồi liên hệ kênh chính thức tương ứng. Chưa rõ nguyên nhân thì không gửi tiếp.","takeaways":["Đã gửi, đã lên chuỗi và đã ghi có là ba trạm khác nhau.","Dùng mã giao dịch (hash) trên trình khám phá khối của đúng mạng.","Chia sẻ hồ sơ với bộ phận hỗ trợ chính thức, không bao giờ chia sẻ cụm từ khôi phục, khóa riêng hay mã xác thực."],"quiz":{"q":"Giao dịch của bạn báo \"đã gửi\" nhưng chưa đến. Bước đầu tiên là gì?","options":["Gửi lại cùng số tiền","Tìm xem nó đang kẹt ở đâu bằng hồ sơ và mã giao dịch","Trả tiền cho người hứa sẽ lấy lại giúp"],"answer":1,"why":"Tìm trạm trước, rồi liên hệ kênh chính thức tương ứng. Đừng tiếp tục gửi."},"transcript":[{"t":0.25,"who":"sam","text":"Vẫn chưa tới. Tôi có nên chuyển thêm vài lần nữa để thử không?"},{"t":9.25,"who":"nexubo","text":"Đừng chuyển tiếp. Đã gửi yêu cầu, đã lên chuỗi và đã vào tài khoản là ba trạng thái khác nhau. Hãy tìm xem kẹt ở đâu rồi mới quyết định liên hệ ai."},{"t":32.25,"who":"narrator","text":"Lưu lại biên lai chuyển khoản. Nếu có mã hash giao dịch, hãy tra cứu trên trình khám phá khối chuẩn của mạng đó: trạng thái, địa chỉ đích và số lượng. Đừng lẫn lộn với chuỗi khác."},{"t":60.25,"who":"nexubo","text":"Sàn nhận có thể cần thêm số lượt xác nhận hoặc duyệt nội bộ. Nếu điền sai coin, mạng, địa chỉ hay memo, hãy dừng gửi ngay và cung cấp chứng từ cho hỗ trợ chính thức."},{"t":84.25,"who":"narrator","text":"Giao dịch đã hoàn tất trên blockchain thường không thể hủy ngang. Khôi phục được hay không tùy thuộc vào điều kiện kỹ thuật và sàn giao dịch; đừng tin ai hứa trả tiền là lấy lại được chắc chắn."},{"t":103.25,"who":"sam","text":"Cung cấp các chứng từ cần thiết, tuyệt đối không đưa cụm từ khôi phục, khóa riêng tư hay mã OTP."},{"t":107.92,"who":"nexubo","text":"Đúng vậy. Xác định vị trí kẹt trước, không chuyển khoản mù quáng."},{"t":116.25,"who":"narrator","text":"'Chào bạn, tôi là hỗ trợ viên. Hãy gửi cụm từ khôi phục cho tôi.' Tập sau: Kẻ lừa đảo thực sự muốn gì."},{"t":122.45,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":11,"title":"Có người bảo giúp bạn kiếm tiền. Hãy xem họ đòi hỏi điều gì trước đã.","goal":"Nhận biết yêu cầu cung cấp khóa bí mật, thanh toán ngoài nền tảng, ủy quyền bất thường và cam kết lợi nhuận.","task":"Chỉ ra các yêu cầu nguy hiểm trong bốn đoạn chat giả định và chọn hướng đi 'dừng lại, xác minh qua kênh chính thức'.","answer":"Nếu bất kỳ ai đòi khóa riêng tư, cụm từ khôi phục, mã OTP hoặc ủy quyền mập mờ, tuyệt đối không làm theo.","takeaways":["Cụm từ khôi phục và khóa riêng là chìa khóa kiểm soát, không phải mã hỗ trợ.","Lợi nhuận được bảo đảm và việc bị hối thúc thanh toán là dấu hiệu nguy hiểm.","Không bao giờ xác nhận một chữ ký hay phê duyệt mà bạn không hiểu."],"quiz":{"q":"Thứ nào an toàn để chia sẻ khi bạn cần nhận thanh toán?","options":["Địa chỉ công khai của bạn","Cụm từ khôi phục của bạn","Mã dùng một lần"],"answer":0,"why":"Địa chỉ công khai được tạo ra để nhận tiền. Bí mật và mã sẽ trao quyền kiểm soát cho người khác."},"transcript":[{"t":0.25,"who":"sam","text":"Anh ta bảo là nhân viên hỗ trợ, muốn giúp tôi nâng cấp ví."},{"t":9.25,"who":"nexubo","text":"Với ví tự quản lý thông thường, cụm từ khôi phục là chìa khóa kiểm soát tối cao, không phải mã xác thực hỗ trợ. Khóa riêng tư cũng vậy. Đừng đưa cho bất kỳ ai, ngay cả trợ lý của khóa học này cũng không được phép hỏi."},{"t":32.25,"who":"narrator","text":"Thêm hai dấu hiệu nguy hiểm: Cam kết sinh lời và hối thúc thanh toán. Ảnh chụp màn hình lợi nhuận khủng không chứng minh được gì. Nếu có ai hối bạn bỏ qua các bước kiểm tra, hãy dừng lại ngay."},{"t":60.25,"who":"nexubo","text":"Kết nối ví, ký tin nhắn và ủy quyền truy cập tài sản là những việc hoàn toàn khác nhau. Nếu không hiểu rõ chữ ký hay ủy quyền, đừng bấm xác nhận. Không yêu cầu mật khẩu không có nghĩa là không có rủi ro."},{"t":84.25,"who":"narrator","text":"Khi nghi ngờ bị lộ thông tin, hãy dừng thao tác và dùng kênh an toàn chính thức để xử lý. Áp dụng biện pháp tương ứng với dữ liệu bị lộ, tuyệt đối không cài phần mềm điều khiển từ xa theo lời kẻ lừa đảo."},{"t":103.25,"who":"sam","text":"Có thể công khai thông tin nhận tiền, nhưng không bao giờ được giao chìa khóa kiểm soát."},{"t":106.72,"who":"nexubo","text":"Không để lộ bí mật, không ủy quyền bừa bãi, không để bị ép chuyển tiền gấp."},{"t":116.25,"who":"narrator","text":"Đã hoàn thành mười một bài học. Đã đến lúc nạp tiền thật chưa? Tập cuối Phần 1 có câu trả lời bất ngờ."},{"t":123.15,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":12,"title":"Tập cuối Phần 1: Bạn có thể làm được, và bạn cũng có quyền không làm","goal":"Hoàn thành bài luyện tập tổng hợp, hiểu rằng không giao dịch là một lựa chọn hợp lệ và biết các bước tiếp theo.","task":"Trả lời ba câu hỏi tổng kết khóa học trong bảng luyện tập.","answer":"Bán lấy USDT không phải là rút về ngân hàng; lên chuỗi không đồng nghĩa đã vào tài khoản; không lộ thông tin xác thực và không chuyển khi chưa rõ.","takeaways":["Mục tiêu là một quy trình đúng: lối vào và điều kiện, giao ngay, số tiền và phí, rồi đến hồ sơ.","Dừng một giao dịch chưa rõ ràng cũng là một câu trả lời đúng.","Chứng chỉ của bạn là hồ sơ học tập, không phải giấy phép đầu tư."],"quiz":{"q":"Một giao dịch luyện tập hiển thị sai mạng. Cách làm đúng là gì?","options":["Cứ gửi và hy vọng","Dừng lại và không gửi","Chuyển sang số tiền lớn hơn"],"answer":1,"why":"Khi mạng, phí hoặc danh tính chưa rõ, dừng lại quan trọng hơn hoàn thành nhiệm vụ."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi đã học xong tất cả các bài. Nghĩa là tôi có thể giao dịch thật được rồi đúng không?"},{"t":9.25,"who":"nexubo","text":"Đừng vội. Hôm nay chúng ta làm một bài kiểm tra mô phỏng toàn diện. Kiểm tra cửa vào, lệnh spot, số tiền và phí, đối chiếu kết quả. Có thắc mắc thì chưa giao dịch."},{"t":39.25,"who":"narrator","text":"Bạn làm đúng là khi nhận diện rõ rủi ro và bình tĩnh kiểm tra. Điểm số bài học không phải là lời hứa hẹn lợi nhuận sau này. Nếu trả lời sai, hãy học lại bài đó."},{"t":75.25,"who":"sam","text":"Thông tin chuyển khoản này có vấn đề, tôi sẽ không chuyển."},{"t":78.5,"who":"nexubo","text":"Đó cũng là câu trả lời hoàn toàn chính xác. Khi mạng lưới, phí hay danh tính chưa rõ ràng, dừng lại còn quan trọng hơn là cố chấp hoàn thành nhiệm vụ."},{"t":106.25,"who":"narrator","text":"Cuối cùng, hãy trả lời ba câu hỏi: Tài sản đã đi đâu? Số tiền thực tế bị trừ là bao nhiêu? Và ai đang kiểm soát tài khoản của bạn? Chưa rõ điểm nào thì quay lại ôn bài đó."},{"t":130.25,"who":"nexubo","text":"Những gì bạn đạt được là kết quả học tập, không phải giấy phép đầu tư. Tiếp tục học hỏi hoặc tạm thời chưa giao dịch đều hoàn toàn ổn. Hiểu rõ trước, hành động sau."},{"t":146.25,"who":"nexubo","text":"Khi bạn quyết định bắt đầu, hãy so sánh các sàn giao dịch trên NexuAlpha. Đăng ký qua liên kết đối tác chính thức kèm mã để được hoàn phí và vào Telegram đón bài học mới."},{"t":157.55,"who":"narrator","text":"Phần 2: Giá bạn thấy trên màn hình chưa chắc là giá bạn phải trả. Đón xem lý do."},{"t":163.05,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":13,"title":"Tại sao giá trên màn hình không phải là giá khớp lệnh của tôi?","goal":"Hiểu sổ lệnh, chênh lệch giá mua-bán (spread), độ sâu thị trường, phí giao dịch và độ trượt giá (slippage).","task":"Khớp 0.002 BTC vào hai mức lệnh bán mô phỏng và tính giá bình quân gia quyền.","answer":"Tổng 100.10, giá bình quân 50,050 trước phí giảng dạy. Nếu tính thêm 0.1% phí bằng USDT: phí 0.1001, tổng chi 100.2001 (không làm tròn trước khi tính).","takeaways":["Giá cuối cùng là giao dịch gần nhất, không phải mức giá chào cho mọi khối lượng.","Lệnh lớn hơn có thể khớp qua nhiều mức của sổ lệnh.","Trượt giá và phí giao dịch là hai chi phí riêng: hãy xem kỹ hóa đơn."],"quiz":{"q":"Một nửa trong 0.002 BTC của bạn khớp ở 50,000 và nửa còn lại ở 50,100. Giá trung bình là bao nhiêu?","options":["50,000","50,050","50,100"],"answer":1,"why":"Hai nửa bằng nhau có trung bình là 50,050. Phí là chi phí riêng cộng thêm."},"transcript":[{"t":0.25,"who":"sam","text":"Vừa nãy rõ ràng giá này, sao hóa đơn của tôi lại khác?"},{"t":9.25,"who":"nexubo","text":"Giá gần nhất trên màn hình là ghi nhận của giao dịch vừa xong, không phải báo giá cho số lượng vô hạn. Muốn biết người ta sẵn sàng mua bán bao nhiêu lúc này, phải nhìn sổ lệnh."},{"t":32.25,"who":"narrator","text":"Giả sử bạn mua 0.002 bitcoin. Mức giá đầu tiên chỉ có một nửa, nửa còn lại phải khớp ở giá cao hơn. Gộp lại thì giá bình quân là 50,050, không phải 50,000."},{"t":60.25,"who":"nexubo","text":"Trượt giá là khoảng cách giữa giá dự kiến và giá thực nhận. Nó không phải lúc nào cũng bất lợi. Phí giao dịch là chi phí riêng biệt; đừng gom chung vào khẩu hiệu 'miễn phí'."},{"t":84.25,"who":"narrator","text":"Lệnh càng lớn, độ sâu càng mỏng hoặc thị trường biến động càng nhanh thì kết quả càng dễ lệch kỳ vọng. Trước khi đặt hãy nhìn số tiền và độ sâu, sau khi khớp hãy nhìn giá trung bình."},{"t":103.25,"who":"sam","text":"Không thể."},{"t":104.04,"who":"nexubo","text":"Chỉ khi nhìn thấy hóa đơn khớp lệnh mới tính là rõ ràng; đừng chỉ nhìn chằm chằm vào con số to nhất trên màn hình."},{"t":116.25,"who":"nexubo","text":"Phí giao dịch là chi phí bạn thực sự có thể giảm bớt. Hãy so sánh phí trên NexuAlpha và đăng ký qua liên kết đối tác kèm mã của chúng tôi để được hoàn phí. Giảm chi phí, rủi ro không đổi."},{"t":126.75,"who":"narrator","text":"Đặt lệnh mua mà mãi không khớp. Hệ thống bị lỗi sao? Tập tiếp theo: Lệnh thị trường, lệnh giới hạn và hủy lệnh."},{"t":132.45,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":14,"title":"Thị trường, giới hạn, hủy lệnh: mỗi loại giải quyết điều gì?","goal":"Chọn lệnh theo 'ưu tiên khớp lệnh' hoặc 'ưu tiên mức giá', và hiểu về lệnh chưa khớp cùng khớp một phần.","task":"Đặt một lệnh giới hạn ảo, quan sát khớp lệnh một phần, sau đó hủy số lượng còn lại.","answer":"Dù điều kiện giá phù hợp nhưng vẫn phụ thuộc vào khối lượng có sẵn; phần đã khớp không thể bị đảo ngược khi hủy lệnh.","takeaways":["Lệnh thị trường khớp nhanh theo giá đang có; giá cuối cùng có thể thay đổi.","Lệnh giới hạn chặn mức giá của bạn, nhưng có thể không khớp.","Hủy lệnh chỉ ảnh hưởng đến phần chưa khớp; phần đã khớp vẫn giữ nguyên."],"quiz":{"q":"Lệnh giới hạn của bạn đã khớp một nửa và bạn hủy nó. Điều gì xảy ra?","options":["Mọi thứ được đảo ngược","Chỉ nửa chưa khớp bị hủy","Nửa đã khớp chuyển thành lệnh thị trường"],"answer":1,"why":"Hủy lệnh không thể tua lại phần đã khớp. Nó chỉ dừng phần khối lượng còn lại."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi đã bấm mua rồi, sao lệnh mãi không khớp?"},{"t":9.25,"who":"nexubo","text":"Lệnh thị trường ưu tiên khớp nhanh nhất có thể theo giá hiện có, nhưng giá thực tế có thể biến động. Lệnh giới hạn quy định mức giá mua tối đa hoặc bán tối thiểu, nhưng không đảm bảo sẽ khớp."},{"t":32.25,"who":"narrator","text":"Nếu muốn mua thấp hơn giá hiện tại, bạn có thể phải chờ đợi. Ngược lại, nếu lệnh giới hạn đã thỏa mãn điều kiện khớp của bên đối ứng, nó có thể khớp ngay lập tức; không phải lệnh giới hạn nào cũng phải xếp hàng chờ."},{"t":60.25,"who":"sam","text":"Vậy hủy lệnh có làm hủy luôn phần tôi vừa mới mua không?"},{"t":62.82,"who":"nexubo","text":"Không. Hủy lệnh chỉ áp dụng cho phần chưa khớp; những tài sản đã khớp thành công sẽ không thể bị đảo ngược."},{"t":84.25,"who":"narrator","text":"Hãy nhìn rõ trạng thái trước khi thao tác. Việc lệnh của bạn là maker hay taker phụ thuộc vào cách nó khớp lệnh thực tế; chọn lệnh giới hạn không đồng nghĩa với việc chắc chắn nhận được mức phí maker."},{"t":103.25,"who":"sam","text":"Không."},{"t":104.12,"who":"nexubo","text":"Chọn lệnh là chọn phương thức thực thi, chứ không phải ước nguyện."},{"t":116.25,"who":"narrator","text":"Cây nến màu xanh có đồng nghĩa với việc cây nến sau cũng sẽ tăng? Tập tiếp theo."},{"t":121.05,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":15,"title":"Một cây nến: bốn điều nó thực sự nói cho bạn là gì?","goal":"Đọc được giá mở, cao, thấp, đóng và khung thời gian; không coi màu sắc hay một mô hình đơn lẻ là dự đoán tương lai.","task":"Nhấp vào giá mở, cao, thấp, đóng trên cây nến ảo và xác nhận khung thời gian của biểu đồ.","answer":"50,000 / 51,000 / 49,000 / 50,500; khung năm phút.","takeaways":["Một cây nến cho thấy bốn mức giá trong một khoảng thời gian: mở cửa, cao nhất, thấp nhất và đóng cửa.","Đọc khung thời gian trước khi nhìn hình dạng: năm phút không phải một ngày.","Màu sắc khác nhau giữa các ứng dụng, và một cây nến là bản ghi, không phải dự đoán."],"quiz":{"q":"Một nến năm phút mở cửa ở 50,000, lên tới 51,000, giảm xuống 49,000 và đóng cửa ở 50,500. Giá cao nhất là bao nhiêu?","options":["50,500","51,000","49,000"],"answer":1,"why":"Đỉnh của bóng nến trên là giá cao nhất trong khoảng thời gian đó: 51,000."},"transcript":[{"t":0.25,"who":"sam","text":"Màu xanh, có phải nghĩa là giây tiếp theo giá vẫn sẽ tăng?"},{"t":9.25,"who":"nexubo","text":"Một cây nến ghi lại bốn mức giá trong một khoảng thời gian: mở cửa, cao nhất, thấp nhất và đóng cửa. Đây là biến động năm phút giả định, không phải sự bảo đảm cho năm phút tới."},{"t":32.25,"who":"narrator","text":"Thân nến giúp bạn thấy chênh lệch giữa giá mở và đóng, bóng nến đánh dấu các điểm cao nhất và thấp nhất trong chu kỳ. Cây nến chưa đóng cửa sẽ tiếp tục thay đổi theo các giao dịch mới."},{"t":60.25,"who":"sam","text":"Tại sao khi chuyển khung thời gian, biểu đồ trông lại khác hẳn?"},{"t":63.75,"who":"nexubo","text":"Độ dài thời gian mà mỗi cây nến đại diện đã thay đổi. Hãy đọc khung thời gian trước rồi mới bàn về hình thái; không thể coi năm phút như một ngày."},{"t":84.25,"who":"narrator","text":"Các ứng dụng có thể dùng màu sắc khác nhau để chỉ tăng giảm, vì vậy hãy nhìn vào chú giải và con số. Dữ liệu lịch sử cung cấp thông tin, nhưng một cây nến đơn lẻ không thể đảm bảo bước tiếp theo sẽ tăng hay giảm."},{"t":103.25,"who":"sam","text":"Cao nhất 51,000, đóng cửa 50,500."},{"t":108.91,"who":"nexubo","text":"Đọc bản ghi trước, đừng biến dữ liệu thành lời tiên tri."},{"t":116.25,"who":"narrator","text":"\"Tôi có 1,000, chỉ muốn chịu lỗ 20, vậy mua hết luôn?\" Tập tiếp theo: tính trước khoản có thể mất."},{"t":122.35,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":16,"title":"Xác định mức có thể mất trước khi quyết định mua bao nhiêu","goal":"Hiểu rằng số dư tài khoản, quy mô vị thế và rủi ro theo kế hoạch là ba con số hoàn toàn khác nhau.","task":"Tính toán vị thế ảo dựa trên điểm vào lệnh, khoảng cách cắt lỗ và ngân sách rủi ro giảng dạy cho trước.","answer":"400 USDT giá trị danh nghĩa giao ngay; 0.008 BTC; phí và độ lệch khớp lệnh phải tính riêng.","takeaways":["Số dư tài khoản, quy mô vị thế và rủi ro dự kiến là ba con số khác nhau.","Quyết định điểm thoát trước, rồi mới tính quy mô vị thế.","Với mức dừng lỗ 5% và ngân sách rủi ro 20, vị thế khoảng 400."],"quiz":{"q":"Vào lệnh ở 50,000, dự kiến thoát ở 47,500, và bạn chấp nhận lỗ 20. Vị thế khoảng bao nhiêu?","options":["20","400","4,000"],"answer":1,"why":"Điểm thoát cách 5%, và 5% của 400 là 20. Chi phí tính thêm bên trên."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi có 1,000 và chỉ muốn chịu lỗ 20, vậy cứ mua hết vào trước?"},{"t":9.25,"who":"nexubo","text":"Số tiền có trong tài khoản, số tiền mua trong lệnh này và mức thua lỗ tối đa dự kiến chấp nhận là ba điều hoàn toàn khác nhau. Phải có điều kiện thoát lệnh trước mới tính được quy mô vị thế."},{"t":35.25,"who":"narrator","text":"Hãy xem một bài tập: vào lệnh ở 50,000, dự kiến thoát ở 47,500, chênh lệch 5%. Nếu bạn dự định chịu rủi ro giá 20 và bỏ qua chi phí, vị thế sẽ khoảng 400."},{"t":67.25,"who":"sam","text":"Hóa ra 'chỉ chịu lỗ tối đa 20' không đồng nghĩa với 'chỉ mua 20'?"},{"t":70.55,"who":"nexubo","text":"Đúng vậy. Ở đây vị thế 400 giảm 5% mới tương ứng với 20; đây chỉ là thông số giảng dạy."},{"t":95.25,"who":"narrator","text":"Thị trường thực tế có trượt giá, khoảng trống giá, phí hoặc lỗi khớp lệnh, vì vậy rủi ro trên kế hoạch không phải là mức trần bảo đảm. Tuyệt đối không vay mượn tiền để làm bài tập hay dùng tiền sinh hoạt cần thiết."},{"t":116.25,"who":"sam","text":"Hai mươi."},{"t":116.98,"who":"nexubo","text":"Hãy tính trước mức tồi tệ nhất bạn có thể chấp nhận, rồi mới xem bạn có thực sự cần giao dịch hay không."},{"t":131.25,"who":"narrator","text":"Đặt sẵn cắt lỗ thì chắc chắn chỉ lỗ đúng số tiền đó sao? Tập tiếp theo: sự thật về cắt lỗ."},{"t":137.75,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":17,"title":"Chốt lời và cắt lỗ là kế hoạch, không phải bảo hiểm","goal":"Hiểu sự khác biệt giữa kích hoạt và khớp lệnh, nhận biết rủi ro khác nhau giữa lệnh cắt lỗ thị trường và cắt lỗ giới hạn.","task":"So sánh kết quả mô phỏng của lệnh cắt lỗ thị trường và cắt lỗ giới hạn trong cùng một đợt giá giảm mạnh.","answer":"Lệnh đầu có thể trượt giá; lệnh sau có thể không khớp. Cả hai đều không phải bảo hiểm bảo toàn vốn.","takeaways":["Dừng lỗ thực thi kế hoạch thoát của bạn; nó không phải bảo hiểm.","Stop-market thoát nhanh nhưng có thể trượt giá khi thị trường biến động nhanh.","Stop-limit chặn mức giá nhưng có thể hoàn toàn không khớp."],"quiz":{"q":"Khi giá giảm mạnh, điều gì có thể xảy ra với lệnh stop-limit?","options":["Luôn khớp ở giá kích hoạt","Có thể không khớp nếu giá lao qua quá nhanh","Nó trở thành bảo hiểm"],"answer":1,"why":"Mức giới hạn bảo vệ giá của bạn, nên lệnh có thể không được khớp khi thị trường chạy nhanh."},"transcript":[{"t":0.25,"who":"sam","text":"Tôi đã đặt lệnh cắt lỗ rồi, nên chắc chắn chỉ mất đúng số tiền đã nhập thôi đúng không?"},{"t":9.25,"who":"nexubo","text":"Cắt lỗ là việc thực thi kế hoạch thoát lệnh khi điều kiện được đáp ứng, chứ không phải bảo hiểm. Kích hoạt điều kiện không đồng nghĩa với việc chắc chắn khớp đúng mức giá đó, cũng không đảm bảo khoản lỗ dừng đúng ở đó."},{"t":32.25,"who":"narrator","text":"Sau khi kích hoạt, lệnh được thực hiện theo giá thị trường để thoát nhanh nhất, nhưng giá thực tế có thể bị trượt. Khi thị trường biến động mạnh hoặc thiếu thanh khoản, chênh lệch có thể lớn hơn."},{"t":60.25,"who":"nexubo","text":"Sau khi kích hoạt, lệnh giới hạn được treo giúp khống chế giá chấp nhận, nhưng có thể không bán được nếu giá lao dốc quá nhanh. Không có loại nào luôn tốt hơn; đó là các sự đánh đổi khác nhau."},{"t":84.25,"who":"narrator","text":"Sau khi thiết lập, hãy kiểm tra lại hướng, số lượng và trạng thái lệnh. Với hợp đồng tương lai, cần xác minh loại giá kích hoạt để tránh đặt cắt lỗ ở vị trí bị thanh lý trước."},{"t":103.25,"who":"sam","text":"Không đảm bảo."},{"t":104.72,"who":"nexubo","text":"Hiểu rõ giới hạn mới có thể coi cắt lỗ là kế hoạch hiệu quả, chứ không phải bùa hộ mệnh."},{"t":116.25,"who":"narrator","text":"Cả hai đều ghi BTC. Nhưng một loại có thể không cho bạn bất kỳ đồng bitcoin nào. Tiếp theo: giao ngay và tương lai."},{"t":123.15,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ","goal":"Phân biệt việc nắm giữ tài sản cơ sở với nắm giữ hợp đồng giá, hiểu rõ hướng của vị thế mua (long) và bán (short).","task":"Ghép trường số dư tài sản giao ngay và vị thế hợp đồng vào đúng trang tương ứng.","answer":"Vị thế hợp đồng tương lai không tương đương với đồng coin có thể rút; khóa học không yêu cầu bạn mở tài khoản thật.","takeaways":["Giao ngay là đổi tài sản này lấy tài sản khác; hợp đồng vĩnh cửu là một vị thế hợp đồng.","Long lãi nếu giá tăng, short lãi nếu giá giảm; đứng sai phía thì lỗ.","Hợp đồng tương lai là một cấu trúc rủi ro khác, không phải cấp độ bạn bắt buộc phải đạt."],"quiz":{"q":"Vị thế hợp đồng tương lai có cho bạn bitcoin để rút ra không?","options":["Có, giống hệt giao ngay","Không, đó là hợp đồng thanh toán lãi và lỗ","Chỉ khi dùng đòn bẩy 10x"],"answer":1,"why":"Hợp đồng vĩnh cửu tuyến tính thanh toán lãi và lỗ trong hợp đồng. Đó không phải số dư coin có thể rút."},"transcript":[{"t":0.25,"who":"sam","text":"Cả hai đều ghi Bitcoin, chẳng phải đều là cùng một kiểu mua bán sao?"},{"t":9.25,"who":"nexubo","text":"Giao ngay thông thường không vay mượn là dùng một tài sản để đổi lấy một tài sản khác. Hợp đồng vĩnh viễn tuyến tính ở đây là nắm giữ vị thế hợp đồng kết toán lãi lỗ theo biến động giá, không tương đương với việc mua được bitcoin có thể rút."},{"t":32.25,"who":"narrator","text":"Mua (long) thường kỳ vọng giá tăng, bán (short) thường kỳ vọng giá giảm. Đoán sai xu hướng thì bên nào cũng thua lỗ. Có thể bán khống không có nghĩa là dễ kiếm tiền hơn."},{"t":60.25,"who":"sam","text":"Tôi có nên nâng cấp từ giao ngay lên hợp đồng tương lai không?"},{"t":62.38,"who":"nexubo","text":"Không cần. Hợp đồng tương lai là một cấu trúc rủi ro khác, không phải cấp bậc bắt buộc phải đạt được; hiểu rõ nó là gì cũng giúp bạn có thể lựa chọn không dùng."},{"t":84.25,"who":"narrator","text":"Giao ngay thông thường không vay mượn không có cơ chế thanh lý do thiếu ký quỹ như hợp đồng, nhưng tài sản vẫn có thể bị sụt giảm giá trị nghiêm trọng. Không bị cưỡng chế thanh lý không đồng nghĩa với việc bảo toàn vốn."},{"t":103.25,"who":"sam","text":"Không."},{"t":103.9,"who":"nexubo","text":"Hãy phân biệt rõ bạn đang giao dịch cái gì trước khi tìm hiểu đòn bẩy."},{"t":116.25,"who":"narrator","text":"Mở đòn bẩy 10x, sàn có tặng không cho bạn 900? Tập tiếp theo."},{"t":121.25,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":19,"title":"Đòn bẩy 10x: tiền nhiều hơn hay rủi ro lớn hơn?","goal":"Phân biệt tiền ký quỹ, vị thế danh nghĩa và tỷ suất lợi nhuận; hiểu tác động của việc chỉnh đòn bẩy khi quy mô vị thế cố định.","task":"Lần lượt chọn chế độ ký quỹ cố định và vị thế cố định, quan sát lãi lỗ bằng tiền sau khi giá biến động.","answer":"Ký quỹ cố định khi tăng đòn bẩy sẽ phóng đại vị thế danh nghĩa; vị thế cố định thì không tự động phóng đại lãi lỗ bằng tiền.","takeaways":["Ký quỹ 100 kiểm soát vị thế 1,000 là đòn bẩy 10x.","Biến động giá tác động lên vị thế, và khoản ký quỹ của bạn gánh kết quả.","Với cùng quy mô vị thế, thay đổi đòn bẩy làm thay đổi ký quỹ, không thay đổi lãi/lỗ."],"quiz":{"q":"Vị thế 1,000 đi ngược hướng bạn 1%, chưa tính phí. Bạn lỗ khoảng bao nhiêu?","options":["1","10","100"],"answer":1,"why":"1% của vị thế 1,000 là khoảng 10, trừ vào ký quỹ của bạn."},"transcript":[{"t":0.25,"who":"sam","text":"Mở đòn bẩy mười lần, có phải sàn tặng không cho tôi 900 không?"},{"t":9.25,"who":"nexubo","text":"Không phải tặng tiền mặt. Nói một cách đơn giản, 100 ký quỹ kiểm soát 1,000 vị thế danh nghĩa chính là đòn bẩy 10x. Biến động giá tác động lên toàn bộ vị thế, và tiền ký quỹ của bạn sẽ gánh chịu lãi lỗ tương ứng."},{"t":35.25,"who":"narrator","text":"Tạm chưa tính phí, nếu giá đi ngược 1%, vị thế 1,000 sẽ lỗ khoảng 10, vị thế 2,000 lỗ khoảng 20. Phần trăm biến động nhìn rất nhỏ nhưng tác động lên số tiền ký quỹ nhỏ lại vô cùng rõ rệt."},{"t":67.25,"who":"nexubo","text":"Một điểm dễ nhầm lẫn nữa: nếu quy mô vị thế không đổi mà chỉ đổi cài đặt đòn bẩy, lãi lỗ bằng tiền cho cùng biên độ giá sẽ không tự dưng nhân đôi; thay đổi chủ yếu là số tiền ký quỹ yêu cầu và lớp đệm rủi ro."},{"t":95.25,"who":"narrator","text":"Thanh lý thực tế còn liên quan đến ký quỹ duy trì, giá đánh dấu và các loại phí; không thể khẳng định 10x là phải giảm đúng 10% mới bị thanh lý. Tuyệt đối không dựa vào phép tính ước lượng này cho giao dịch thật."},{"t":116.25,"who":"sam","text":"Không."},{"t":117.06,"who":"nexubo","text":"Thứ được phóng đại là tác động của vị thế lên vốn gốc, chứ không phải khả năng phán đoán của bạn."},{"t":131.25,"who":"narrator","text":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ cạn hết? Tập tiếp theo: đường ranh giới vô hình."},{"t":137.05,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":20,"title":"Tại sao bạn có thể bị đóng vị thế trước khi tiền ký quỹ về không?","goal":"Phân biệt giữa ký quỹ ban đầu, ký quỹ duy trì, vốn chủ sở hữu và số dư khả dụng.","task":"Với số vốn ban đầu 100, lỗ tạm tính 20 (chưa tính phí), hãy điền vốn đơn giản hóa 80; xác định các trường số liệu thay đổi.","answer":"Vốn chủ sở hữu 80; yêu cầu duy trì phải tính riêng theo quy tắc sản phẩm, không thể cố định coi bằng mức ký quỹ ban đầu.","takeaways":["Ký quỹ ban đầu dùng để mở vị thế; ký quỹ duy trì giữ cho vị thế còn mở.","Vốn chủ sở hữu là ký quỹ cộng hoặc trừ kết quả đang mở: 100 lỗ 20 còn 80.","Hệ thống rủi ro có thể can thiệp trước khi ký quỹ của bạn cạn về không."],"quiz":{"q":"Ký quỹ ban đầu là 100 và vị thế đang lỗ 20, chưa tính phí. Vốn chủ sở hữu đơn giản hóa là bao nhiêu?","options":["100","80","120"],"answer":1,"why":"100 trừ khoản lỗ 20 còn 80, và vùng đệm tiếp tục thu hẹp nếu giá đi tiếp ngược hướng bạn."},"transcript":[{"t":0.25,"who":"sam","text":"Vẫn còn số dư mà, tại sao không cho tôi tiếp tục chờ?"},{"t":9.25,"who":"nexubo","text":"Mở vị thế cần ký quỹ ban đầu; trong quá trình giữ vị thế, bạn còn phải đáp ứng yêu cầu ký quỹ duy trì. Số tiền nạp ban đầu không đồng nghĩa với lớp đệm rủi ro duy trì suốt thời gian sau."},{"t":35.25,"who":"narrator","text":"Giả sử ký quỹ ban đầu là 100, vị thế đang tạm lỗ 20, bỏ qua các yếu tố khác thì vốn liên quan chỉ còn lại 80. Nếu giá tiếp tục biến động bất lợi, lớp đệm khả dụng sẽ tiếp tục co hẹp."},{"t":67.25,"who":"nexubo","text":"Khi vốn chủ sở hữu tiến gần đến mức duy trì yêu cầu của sàn, hệ thống quản trị rủi ro có thể can thiệp ngay; không nhất thiết phải chờ đến khi số dư về không. Điều này phụ thuộc vào loại tài khoản, chế độ ký quỹ và quy tắc sản phẩm."},{"t":95.25,"who":"sam","text":"Vậy tôi cứ liên tục nạp thêm tiền là an toàn đúng không?"},{"t":99.06,"who":"nexubo","text":"Nạp thêm tiền không làm thay đổi hướng đi của giá, cũng không đảm bảo bạn không bị thanh lý. Nó có thể chỉ khiến nhiều tiền hơn bị cuốn vào cùng một rủi ro."},{"t":116.25,"who":"sam","text":"Không phải, một bên là điều kiện mở vị thế, một bên là yêu cầu duy trì khi đang giữ lệnh."},{"t":121.2,"who":"nexubo","text":"Trước tiên hãy nhìn vào vốn chủ sở hữu, rồi xem nó cách vạch cảnh báo bao xa."},{"t":131.25,"who":"narrator","text":"Bỏ 100 vào chiếc hộp nhỏ, 900 còn lại có mãi mãi an toàn không? Tập tiếp theo: ký quỹ cô lập."},{"t":137.95,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":21,"title":"Ký quỹ cô lập: đặt giao dịch này vào chiếc hộp riêng biệt","goal":"Hiểu về sự cô lập ký quỹ cho từng vị thế và việc bổ sung ký quỹ có thể mở rộng số vốn chịu rủi ro.","task":"Tìm công tắc tự động bổ sung trong cài đặt mô phỏng và giải thích lý do nó làm thay đổi lượng vốn gánh chịu rủi ro.","answer":"Bổ sung ký quỹ tự động hoặc thủ công đều làm tăng tiền ký quỹ chịu rủi ro; không thể cam kết vô điều kiện rằng chỉ lỗ số tiền ban đầu.","takeaways":["Ký quỹ cô lập cho mỗi vị thế một khoản ký quỹ riêng.","Khoản ký quỹ bạn đã phân bổ vẫn có thể mất; cô lập không phải là dừng lỗ.","Tự động thêm hay thêm thủ công đều đặt thêm tiền của bạn sau cùng một rủi ro."],"quiz":{"q":"Bạn bật tự động thêm ký quỹ cho một vị thế cô lập. Điều gì thay đổi?","options":["Không gì cả, khoản lỗ vẫn giới hạn ở 100 ban đầu","Thêm số dư của bạn có thể chảy vào vị thế","Vị thế trở nên không rủi ro"],"answer":1,"why":"Tự động thêm sẽ chuyển số dư khả dụng vào vị thế, nên nhiều tiền hơn gánh rủi ro."},"transcript":[{"t":0.25,"who":"sam","text":"Bỏ 100 vào làm ký quỹ cô lập, 900 còn lại sẽ mãi mãi không bị đụng tới sao?"},{"t":9.25,"who":"nexubo","text":"Cốt lõi của ký quỹ cô lập là phân bổ tiền ký quỹ riêng cho từng vị thế. Trong điều kiện đơn giản hóa không bổ sung và không bật tự động bổ sung, rủi ro thanh lý chủ yếu do số tiền ký quỹ được phân bổ gánh chịu."},{"t":32.25,"who":"narrator","text":"Nó giúp phân định ranh giới ký quỹ cho các vị thế. Nhưng chính 100 đó vẫn có thể bị mất sạch; ký quỹ cô lập không làm biến mất thua lỗ, cũng không phải lệnh cắt lỗ."},{"t":60.25,"who":"nexubo","text":"Hãy chú ý công tắc này: một số sàn cung cấp tính năng tự động bổ sung ký quỹ. Khi bật, số dư khả dụng có thể tiếp tục chảy vào vị thế. Bổ sung thủ công cũng vậy, đều khiến nhiều tiền hơn chịu rủi ro."},{"t":84.25,"who":"narrator","text":"Đừng chỉ nhìn vào hai chữ 'cô lập' mà mặc định mức lỗ tối đa sẽ mãi mãi bằng 100 ban đầu. Bạn cần kiểm tra kỹ cài đặt bổ sung ký quỹ, phí và quy tắc sản phẩm."},{"t":103.25,"who":"sam","text":"Không thể."},{"t":103.99,"who":"nexubo","text":"Ký quỹ cô lập cần nhìn vào phạm vi cách ly, đồng thời phải xem có đường ống nào được nối thêm vào hay không."},{"t":116.25,"who":"narrator","text":"Một vị thế rò rỉ nước, vị thế kia cũng bắt đầu chìm theo. Tập tiếp theo: ký quỹ chéo."},{"t":121.15,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":22,"title":"Ký quỹ chéo: vì sao một vị thế lỗ có thể ảnh hưởng đến các vị thế khác","goal":"Hiểu rủi ro dùng chung trong cùng một quỹ ký quỹ, không nhầm lẫn ký quỹ chéo với toàn bộ tài sản cá nhân.","task":"Để một vị thế ảo bị lỗ, quan sát rủi ro thay đổi trong cùng quỹ và khoanh tròn những tài sản không nằm trong quỹ ký quỹ này.","answer":"Rủi ro có thể lan sang cùng quỹ ký quỹ. Nó không tự động bao gồm toàn bộ tài sản cá nhân.","takeaways":["Ký quỹ chéo dùng chung một quỹ ký quỹ cho các vị thế.","Một vị thế thua lỗ có thể ăn mòn vùng đệm mà các vị thế khác dựa vào.","Nó không chạm đến thẻ ngân hàng hay ví cá nhân của bạn."],"quiz":{"q":"Ký quỹ chéo có tự động an toàn hơn không?","options":["Có, nó không bao giờ bị thanh lý","Không hẳn, còn tùy vào quỹ chung và quy tắc","Có, nó dùng tất cả thẻ ngân hàng của bạn"],"answer":1,"why":"Ký quỹ bổ sung có thể trì hoãn việc xử lý rủi ro, nhưng cũng đặt thêm tiền của bạn vào thế rủi ro."},"transcript":[{"t":0.25,"who":"sam","text":"Khoản lỗ nằm ở vị thế bên trái. Tại sao vị thế bên phải cũng gặp nguy hiểm?"},{"t":9.25,"who":"nexubo","text":"Ký quỹ chéo chia sẻ tiền ký quỹ giữa các vị thế, trong phạm vi quy tắc cho phép. Giả sử một quỹ ký quỹ có 1,000. Nhiều vị thế có thể dựa vào đó, chứ không chỉ dựa vào số tiền phân bổ ban đầu cho từng vị thế."},{"t":39.25,"who":"narrator","text":"Một vị thế thua lỗ có thể bào mòn lớp đệm mà các vị thế khác đang dựa vào. Lợi nhuận, thua lỗ, tiền ký quỹ bị giữ cho các lệnh chờ và giá trị tài sản thế chấp đều có thể ảnh hưởng đến rủi ro của cùng một tài khoản."},{"t":75.25,"who":"sam","text":"Vậy ký quỹ chéo khó bị thanh lý hơn, nghĩa là nó an toàn hơn sao?"},{"t":79.67,"who":"nexubo","text":"Số tiền bổ sung có thể trì hoãn thời điểm một vị thế bị kích hoạt xử lý rủi ro. Nhưng nó cũng đem nhiều tiền của bạn ra gánh chịu thua lỗ hơn."},{"t":106.25,"who":"narrator","text":"Ký quỹ chéo không cho phép nền tảng tự ý đụng đến thẻ ngân hàng hay ví cá nhân của bạn. Tài khoản và tài sản thế chấp nào được tính phụ thuộc vào quy tắc sản phẩm. Tài sản thế chấp phức tạp cũng có thể bị chiết khấu định giá (haircut) và chịu rủi ro biến động giá riêng."},{"t":130.25,"who":"sam","text":"Không nhất thiết. Điều đó phụ thuộc vào quỹ dùng chung và quy tắc tài khoản."},{"t":135.19,"who":"nexubo","text":"Hãy nhìn vào toàn bộ quỹ, chứ không chỉ ô của một vị thế."},{"t":146.25,"who":"narrator","text":"Giá bạn theo dõi chưa chạm vạch, nhưng còi báo động đã reo. Tiếp theo: ai là người bấm nút thanh lý."},{"t":152.55,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":23,"title":"Thanh lý: ai đã nhấn nút buộc đóng vị thế?","goal":"Hiểu các yếu tố kích hoạt thanh lý, giá đánh dấu và yêu cầu duy trì ký quỹ, không dùng công thức nghịch đảo đòn bẩy làm công thức chính xác tuyệt đối.","task":"Mô phỏng cùng một biểu đồ ảo giảm rồi tăng, và quan sát riêng biệt giữa giao ngay thông thường và hợp đồng cô lập đơn giản hoá.","answer":"Đường đi của giá rất quan trọng. Hợp đồng bị thanh lý giữa chừng sẽ không tự phục hồi khi giá bật tăng trở lại.","takeaways":["Nhiều hợp đồng vĩnh cửu xét thanh lý theo giá đánh dấu (mark price) và quy tắc ký quỹ, không theo giao dịch cuối cùng.","Khi gần đến mức ký quỹ duy trì, hệ thống có thể giảm hoặc đóng vị thế.","Vị thế đã đóng sẽ không quay lại khi giá phục hồi."],"quiz":{"q":"Một vị thế dùng đòn bẩy đã bị thanh lý, sau đó giá tăng trở lại. Điều gì xảy ra?","options":["Vị thế tự quay lại","Nó vẫn đóng; diễn biến giá trên đường đi mới là điều quyết định","Sàn hoàn lại khoản lỗ"],"answer":1,"why":"Một khi bị đóng cưỡng bức, vị thế đã mất. Đợt phục hồi sau đó chỉ có lợi cho người vẫn đang nắm giữ."},"transcript":[{"t":0.25,"who":"sam","text":"Mức giá tôi đang nhìn vẫn chưa tới đó. Tại sao chuông báo động lại reo?"},{"t":9.25,"who":"nexubo","text":"Giá khớp lệnh gần nhất không phải lúc nào cũng là mức giá dùng để xác định thanh lý. Nhiều hợp đồng vĩnh viễn đánh giá rủi ro dựa trên giá đánh dấu (mark price) và quy tắc ký quỹ. Hãy kiểm tra xem nền tảng của bạn áp dụng quy tắc nào."},{"t":35.25,"who":"narrator","text":"Khi giá đi ngược chiều vị thế, khoản lỗ sẽ ăn mòn vốn chủ sở hữu. Khi gần chạm mức ký quỹ duy trì, hệ thống có thể hủy lệnh chờ, giảm vị thế hoặc cưỡng chế đóng vị thế. Hệ thống sẽ không đợi sự đồng ý của bạn."},{"t":67.25,"who":"nexubo","text":"Thanh lý thường là sự kiện rủi ro bị buộc đóng vị thế này, chứ không phải nút bấm trên điện thoại bị hỏng. Kích hoạt thực tế phụ thuộc vào phí, ký quỹ duy trì, chế độ ký quỹ và nhiều yếu tố khác. Đòn bẩy 10x không có nghĩa là giá giảm đúng 10% là bị thanh lý."},{"t":95.25,"who":"sam","text":"Sau đó giá tăng lại mà. Tôi không thể cứ chờ giá quay lại sao?"},{"t":99.46,"who":"nexubo","text":"Một vị thế đã bị đóng sẽ không tự quay trở lại. Cùng một đợt giá giảm rồi tăng có thể kết thúc rất khác nhau giữa vị thế đòn bẩy và việc bạn chỉ nắm giữ giao ngay thông thường."},{"t":116.25,"who":"sam","text":"Không có gì đảm bảo."},{"t":117.73,"who":"nexubo","text":"Vấn đề không chỉ là điểm đến. Mà là bạn có thể sống sót qua hành trình đó hay không."},{"t":131.25,"who":"narrator","text":"Giá hầu như không đổi và bạn không đóng lệnh, nhưng số dư vẫn giảm. Tập cuối cùng sẽ giải thích điều này."},{"t":137.35,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]},{"ep":24,"title":"Giá đi ngang, số dư giảm? Vượt qua ải cuối với bài toán chi phí","goal":"Nắm rõ hướng và cơ sở tính phí funding, kiểm tra rủi ro hợp đồng tương lai toàn diện và biết cách chủ động chọn không giao dịch.","task":"Tính phí một kỳ là 0.10 và hoàn thành bảng kiểm tra lệnh tương lai ảo. Tuyệt đối không gọi API đặt lệnh thật.","answer":"Tỷ lệ dương: bên mua trả, bên bán nhận. Phí trong ví dụ này: 0.10. Vượt qua bằng cách trả lời đúng mọi câu hỏi rủi ro cốt lõi, hoặc chủ động chọn không giao dịch.","takeaways":["Phí funding được trả giữa bên long và bên short, không phải khoản phí cố định cho sàn.","Nó tính theo giá trị vị thế: 1,000 với 0.01% là 0.10.","Chọn không giao dịch cũng là một câu trả lời đạt."],"quiz":{"q":"Funding rate đang dương. Ai thường là bên trả?","options":["Short trả cho long","Long trả cho short","Mọi người trả cho sàn"],"answer":1,"why":"Khi tỷ lệ dương, bên long thường trả cho bên short. Khi tỷ lệ âm thì ngược lại."},"transcript":[{"t":0.25,"who":"sam","text":"Giá hầu như không đổi và tôi không đóng lệnh. Tại sao số dư của tôi lại giảm?"},{"t":9.25,"who":"nexubo","text":"Ngoài phí giao dịch, hợp đồng vĩnh viễn thường có cơ chế phí funding. Khi tỷ lệ dương, bên mua thường trả phí cho bên bán. Khi tỷ lệ âm thì ngược lại. Đây không phải là khoản lãi suất cố định mà ai cũng phải trả cho sàn."},{"t":42.25,"who":"narrator","text":"Giả sử giá trị vị thế tại thời điểm kết toán là 1,000 và tỷ lệ là 0.01%. Khoản phí này là 0.10. Nó được tính trên toàn bộ giá trị vị thế, chứ không phải trên mức ký quỹ 100 ban đầu."},{"t":83.25,"who":"nexubo","text":"Khoảng thời gian và tỷ lệ có thể thay đổi tùy theo cặp giao dịch, sàn và thị trường. Đừng ghi nhớ máy móc là 'mọi hợp đồng, cứ mỗi tám giờ, mãi mãi'. Và đừng bao giờ coi việc nhận phí funding là thu nhập không có rủi ro."},{"t":117.25,"who":"narrator","text":"Cấp độ cuối cùng chỉ dùng để luyện tập. Trước hết hãy nói rõ bạn đang giao dịch cái gì và theo hướng nào. Sau đó kiểm tra chế độ, quy mô, tiền ký quỹ, tính năng tự thêm ký quỹ, kế hoạch thoát lệnh và chi phí. Nếu chưa hiểu rõ dù chỉ một mục, hãy dừng lại. Đừng bấm bừa các nút."},{"t":144.25,"who":"sam","text":"Tôi biết cách vận hành, và tôi biết mức rủi ro này không phù hợp với mình. Nên tôi sẽ không giao dịch."},{"t":149.09,"who":"nexubo","text":"Đó cũng là một kết quả đạt yêu cầu. Hoàn thành khóa học không đồng nghĩa với việc bạn sẽ kiếm được tiền. Hiểu rõ trước, hành động sau."},{"t":161.25,"who":"nexubo","text":"Dù bạn giao dịch gì, phí luôn tích tụ dần. So sánh biểu phí các sàn trên NexuAlpha và chỉ truy cập các trang web chính thức."},{"t":172.75,"who":"narrator","text":"Bạn đã hoàn thành cả hai mùa. Hãy chọn tập bạn thấy khó nhất và xem lại trước khi bắt đầu giao dịch thật."},{"t":178.65,"who":"narrator","text":"Hiểu rõ trước, hành động sau."}]}]});
